export async function pedirPermiso(): Promise<boolean> {
  const N = await mod();
  if (!N) return false;
  try {
    const actual = await N.getPermissionsAsync();
    if (actual.granted) return true;
    if (!actual.canAskAgain) return false;
    const r = await N.requestPermissionsAsync();
    return r.granted;
  } catch {
    return false;
  }
}

// Teléfono de juguete: modela la regla de Android 11 o más (después de dos negativas, el sistema ya no muestra el cuadro)
function crearTelefono() {
  const e = { concedido: false, negativas: 0, cuadros: 0 };
  return {
    consultar: () => ({ granted: e.concedido, canAskAgain: e.negativas < 2 }),
    pedir(decide) {
      if (e.negativas >= 2) return { granted: false, canAskAgain: false };
      e.cuadros++;
      if (decide === "permitir") { e.concedido = true; return { granted: true, canAskAgain: true }; }
      e.negativas++;
      return { granted: false, canAskAgain: e.negativas < 2 };
    },
    cuadros: () => e.cuadros,
  };
}

// La lógica de pedirPermiso de Senda, con el teléfono de juguete en lugar del módulo real
function pedirPermiso(tel, decide) {
  const actual = tel.consultar();
  if (actual.granted) return true;
  if (!actual.canAskAgain) return false;
  return tel.pedir(decide).granted;
}

const tel = crearTelefono();
for (const intento of [1, 2, 3, 4]) {
  const ok = pedirPermiso(tel, "no permitir");
  console.log(`intento ${intento}: ok=${ok}, cuadros mostrados hasta ahora=${tel.cuadros()}, ${JSON.stringify(tel.consultar())}`);
}
